/* Formatted on 9/27/2026 6:18:45 PM (QP5 v5.362) */
DECLARE
    V_ACTIVITY_ID          RAW (16);
    V_ACTIVITY_REASON_ID   RAW (16);
BEGIN
    V_ACTIVITY_ID :='{{ tblApproval.triggeredRow.ACTIVITY_ID }}';
		V_ACTIVITY_REASON_ID :='{{ iReason.selectedOptionValue }}';


    TALY_BO_REP.MMS_APPROVAL_PKG.DECIDE_ACTIVITY (
        P_ACTIVITY_ID          => V_ACTIVITY_ID,
        P_USER_ID              => '{{ appsmith.user.email }}',
        P_DECISION             => '{{ appsmith.store.confirmAction }}',
        P_ACTIVITY_REASON_ID   => V_ACTIVITY_REASON_ID,
        P_DECISION_COMMENT     => NULLIF ('{{ iNote.text }}', ''));

    COMMIT;
END;
